<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <title>可衣 - 商品详情</title>
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <style>
        body{font-family:Arial,sans-serif;margin:0;background:#f5f5f5;color:#333}
        a{text-decoration:none;color:#0078d7}
        header{background:#fff;padding:20px;box-shadow:0 2px 4px rgba(0,0,0,.1);display:flex;justify-content:space-between;align-items:center}
        nav a{margin:0 15px;font-weight:500}
        .container{max-width:1000px;margin:30px auto;background:#fff;padding:20px;border-radius:8px;box-shadow:0 2px 6px rgba(0,0,0,.05)}
        .product-img{width:100%;height:400px;background:#e0e0e0;display:flex;align-items:center;justify-content:center;font-size:2rem;color:#777}
        .details{margin-top:20px}
        .details h2{margin:0 0 10px}
        .price{color:#e53935;font-size:1.5rem;font-weight:bold;margin:10px 0}
        .size-select{margin:15px 0}
        .size-select label{margin-right:10px}
        button{background:#0078d7;color:#fff;border:none;padding:12px 24px;border-radius:4px;cursor:pointer}
        button:disabled{background:#aaa;cursor:not-allowed}
        footer{background:#212121;color:#fff;padding:20px;text-align:center;font-size:.9rem}
        @media(max-width:768px){
            .product-img{height:250px}
        }
    </style>
</head>
<body>
<header>
    <div><strong>可衣</strong></div>
    <nav>
        <a href="index.html">首页</a>
        <a href="products.html">商品</a>
        <a href="cart.html">购物车</a>
    </nav>
</header>

<div class="container" id="productContainer">
    <div class="product-img" id="productImg">商品图片</div>
    <div class="details">
        <h2 id="productName">商品名称</h2>
        <div class="price" id="productPrice">¥ 0</div>
        <div class="size-select">
            <span>选择尺码：</span>
            <select id="sizeSelect">
                <option value="">请选择</option>
            </select>
        </div>
        <button id="addToCartBtn" disabled>加入购物车</button>
    </div>
</div>

<footer>
    © 2024 可衣 上海市 | <a href="mailto:service@keyi.com" style="color:#fff">客服邮箱</a>
</footer>

<script>
    // 商品数据（在真实项目中会通过后端或API获取）
    const PRODUCTS = [
        {
            id: 1,
            name: "简约职场套装",
            price: 398,
            sizes: ["S", "M", "L", "XL"],
            imgAlt: "职场套装"
        },
        {
            id: 2,
            name: "轻盈休闲连衣裙",
            price: 259,
            sizes: ["S", "M", "L"],
            imgAlt: "休闲连衣裙"
        },
        {
            id: 3,
            name: "柔软针织毛衣",
            price: 329,
            sizes: ["M", "L", "XL", "XXL"],
            imgAlt: "针织毛衣"
        }
    ];

    // 简单的本地存储购物车实现
    const Cart = {
        get() {
            return JSON.parse(localStorage.getItem('keiy_cart')||'[]');
        },
        set(items){
            localStorage.setItem('keiy_cart', JSON.stringify(items));
        },
        add(item){
            const items = this.get();
            const exist = items.find(i=>i.id===item.id && i.size===item.size);
            if(exist){
                exist.quantity += item.quantity;
            }else{
                items.push(item);
            }
            this.set(items);
        }
    };

    // 读取 URL 参数
    function getQueryParam(name){
        const params = new URLSearchParams(window.location.search);
        return params.get(name);
    }

    function renderProduct(){
        const pid = parseInt(getQueryParam('id'));
        const product = PRODUCTS.find(p=>p.id===pid);
        if(!product){
            document.getElementById('productContainer').innerHTML = '<p>未找到商品。</p>';
            return;
        }
        document.getElementById('productName').textContent = product.name;
        document.getElementById('productPrice').textContent = '¥ ' + product.price;
        // 用占位图
        const imgDiv = document.getElementById('productImg');
        imgDiv.textContent = product.imgAlt;
        // 填充尺码
        const sizeSel = document.getElementById('sizeSelect');
        product.sizes.forEach(s=>{
            const opt=document.createElement('option');
            opt.value=s;opt.textContent=s;
            sizeSel.appendChild(opt);
        });
        // 监听尺码选择
        sizeSel.addEventListener('change',()=> {
            document.getElementById('addToCartBtn').disabled = sizeSel.value==='';
        });
        // 加入购物车按钮
        document.getElementById('addToCartBtn').addEventListener('click',()=> {
            const chosenSize = sizeSel.value;
            if(chosenSize==='')return;
            Cart.add({id:product.id, name:product.name, price:product.price, size:chosenSize, quantity:1});
            alert('已加入购物车');
        });
    }

    renderProduct();
</script>
</body>
</html>

